create extension if not exists pgcrypto;
create table public.households(id uuid primary key default gen_random_uuid(),name text not null,created_at timestamptz default now());
create table public.household_members(household_id uuid references public.households on delete cascade,user_id uuid references auth.users on delete cascade,role text default 'member',primary key(household_id,user_id),unique(user_id));
create table public.household_invites(id uuid primary key default gen_random_uuid(),household_id uuid references public.households on delete cascade,code text unique not null,created_by uuid references auth.users,expires_at timestamptz default now()+interval '7 days',used_at timestamptz);
create table public.routes(id uuid primary key default gen_random_uuid(),household_id uuid references public.households on delete cascade,route_date date not null,onix_km_initial numeric,onix_km_final numeric,onix_km numeric,logan_km_initial numeric,logan_km_final numeric,logan_km numeric,total_km numeric not null,packages integer not null check(packages>=0),package_cost numeric(12,2) not null check(package_cost>=0),earnings numeric(12,2) not null,notes text,created_by uuid references auth.users,created_at timestamptz default now(),check((onix_km_initial is null and onix_km_final is null and onix_km is null) or (onix_km_initial is not null and onix_km_final is not null and onix_km is not null)),check((logan_km_initial is null and logan_km_final is null and logan_km is null) or (logan_km_initial is not null and logan_km_final is not null and logan_km is not null)),check(onix_km_final>=onix_km_initial),check(logan_km_final>=logan_km_initial));
alter table public.households enable row level security; alter table public.household_members enable row level security; alter table public.household_invites enable row level security; alter table public.routes enable row level security;
create or replace function public.is_household_member(p_household_id uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.household_members m where m.household_id=p_household_id and m.user_id=auth.uid()); $$;
revoke all on function public.is_household_member(uuid) from public;
grant execute on function public.is_household_member(uuid) to authenticated;
create policy "household member read" on public.households for select to authenticated using(public.is_household_member(id));
create policy "membership read" on public.household_members for select to authenticated using(user_id=auth.uid() or public.is_household_member(household_id));
create policy "routes select" on public.routes for select to authenticated using(public.is_household_member(household_id));
create policy "routes insert" on public.routes for insert to authenticated with check(created_by=auth.uid() and public.is_household_member(household_id));
create policy "routes update" on public.routes for update to authenticated using(public.is_household_member(household_id)) with check(public.is_household_member(household_id));
create policy "routes delete" on public.routes for delete to authenticated using(public.is_household_member(household_id));
create or replace function public.create_household(p_name text) returns uuid language plpgsql security definer set search_path=public as $$ declare hid uuid; begin if auth.uid() is null then raise exception 'Faça login'; end if; if exists(select 1 from public.household_members where user_id=auth.uid()) then raise exception 'Conta já vinculada'; end if; insert into public.households(name) values(trim(p_name)) returning id into hid; insert into public.household_members values(hid,auth.uid(),'owner'); return hid; end $$;
create or replace function public.create_household_invite() returns text language plpgsql security definer set search_path=public as $$ declare hid uuid; c text; begin select household_id into hid from public.household_members where user_id=auth.uid(); if hid is null then raise exception 'Sem espaço'; end if; c=upper(encode(extensions.gen_random_bytes(6),'hex')); insert into public.household_invites(household_id,code,created_by) values(hid,c,auth.uid()); return c; end $$;
create or replace function public.join_household_by_code(p_code text) returns uuid language plpgsql security definer set search_path=public as $$ declare inv public.household_invites%rowtype; begin if auth.uid() is null then raise exception 'Faça login'; end if; if exists(select 1 from public.household_members where user_id=auth.uid()) then raise exception 'Conta já vinculada'; end if; select * into inv from public.household_invites where code=upper(trim(p_code)) and used_at is null and expires_at>now() for update; if inv.id is null then raise exception 'Código inválido/expirado'; end if; insert into public.household_members values(inv.household_id,auth.uid(),'member'); update public.household_invites set used_at=now() where id=inv.id; return inv.household_id; end $$;
grant execute on function public.create_household(text),public.create_household_invite(),public.join_household_by_code(text) to authenticated;
grant select on public.households,public.household_members to authenticated; grant select,insert,update,delete on public.routes to authenticated;
